#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-maker. The prefabs are rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/Slash360/Plan.md
    // 360 degree spin slash for 5 elements. Mesh + UV (SM_VFX_Slash_Circle_Thin) with the three Coloso shaders
    // (VFXLib/ColosoShaderAdditive|Alpha|AlphaCutOut_Optimized), used the way the rpg-game slash materials use them:
    //   MainTex = grey shape (alpha = crescent, baked by Docs/VFX/Slash360/bake_slash_textures.py), colour from the particle
    //   (Color over Lifetime) or, on the Additive shader, from _ColorTex (ramp across the band); MaskTex = T_VFX_Gradient_01
    //   fades both ends of the mesh. Vertex streams Position, Color, UV, Custom1XYZW:
    //   Custom1.x dissolve (1 visible .. 0 gone), .y distortion multiplier, .zw main UV offset (UseMainUVCustom1ZW):
    //   z = head position / window slides the crescent round the ring.
    public static class Slash360Build
    {
        const string Root = "Assets/VFX/Slash360";
        const string MeshPath = "Assets/VFX/_Imported/Mesh/SM_VFX_Slash_Circle_Thin.fbx";
        const string Noise = "Assets/VFX/_Shared/Textures/Noise/";
        const string ShAdd = "VFXLib/ColosoShaderAdditive_Optimized";
        const string ShAlpha = "VFXLib/ColosoShaderAlpha_Optimized";
        const string ShCut = "VFXLib/ColosoShaderAlphaCutOut_Optimized";

        const float Life = 0.35f;        // one slash
        const float Swing = 0.8f;        // fraction of life the head spends moving
        const float Radius = 2f;         // outer radius of the ring in metres
        const float MeshOuter = 1.28f;   // outer radius of SM_VFX_Slash_Circle_Thin at scale 1 (inner 0.76)
        const float Tilt = 25f;          // tilt along the sword arm
        const float HipHeight = 1f;      // ring centre above the anchor

        class Element
        {
            public string name, kind;        // kind: Additive / Alpha / Cutout
            public Color core, mid, outer;
            public float window, opacity, cutoff;
            public Vector2 tile, flow;       // detail (MaskTex) tiling and scroll
            public string debris;            // spark / crystal / bubble / rock
        }

        static Color C(float r, float g, float b) => new Color(r, g, b, 1f);

        static readonly Element[] Elements =
        {
            new Element { name = "Fire", kind = "Additive", core = C(1f, 0.93f, 0.68f), mid = C(1f, 0.5f, 0.08f), outer = C(0.8f, 0.12f, 0.03f),
                window = 0.55f, opacity = 1.2f, tile = new Vector2(6f, 1.5f), flow = new Vector2(-1.6f, 0f), debris = "spark" },
            new Element { name = "Ice", kind = "Additive", core = C(0.92f, 1f, 1f), mid = C(0.4f, 0.8f, 1f), outer = C(0.12f, 0.4f, 0.95f),
                window = 0.5f, opacity = 1.2f, tile = new Vector2(8f, 2f), flow = Vector2.zero, debris = "crystal" },
            new Element { name = "Lightning", kind = "Additive", core = C(1f, 1f, 1f), mid = C(1f, 0.9f, 0.3f), outer = C(0.55f, 0.3f, 1f),
                window = 0.5f, opacity = 1.3f, tile = new Vector2(10f, 3f), flow = new Vector2(-6f, 0f), debris = "spark" },
            new Element { name = "Poison", kind = "Alpha", core = C(0.85f, 1f, 0.3f), mid = C(0.32f, 0.82f, 0.18f), outer = C(0.2f, 0.1f, 0.3f),
                window = 0.6f, opacity = 1f, tile = new Vector2(5f, 1.5f), flow = new Vector2(-0.6f, 0f), debris = "bubble" },
            new Element { name = "Earth", kind = "Cutout", core = C(0.95f, 0.8f, 0.5f), mid = C(0.6f, 0.4f, 0.22f), outer = C(0.28f, 0.17f, 0.1f),
                window = 0.5f, opacity = 1f, cutoff = 0.4f, tile = new Vector2(4f, 1.2f), flow = Vector2.zero, debris = "rock" },
        };

        [MenuItem("VFX/Slash360/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");

            var mesh = AssetDatabase.LoadAssetAtPath<Mesh>(MeshPath);
            if (mesh == null) throw new System.InvalidOperationException("Mesh missing: " + MeshPath);
            foreach (var sh in new[] { ShAdd, ShAlpha, ShCut })
            {
                var s = Shader.Find(sh);
                if (s == null || !s.isSupported) throw new System.InvalidOperationException("Shader unavailable: " + sh);
            }

            var glow = ImportTexture(Root + "/Textures/T_Slash360_Glow.png", 256, alphaFromGray: true);
            var white = ImportTexture(Root + "/Textures/T_Slash360_White.png", 32, alphaFromGray: true);
            var dissolve = AssetDatabase.LoadAssetAtPath<Texture2D>(Noise + "T_Noise_Smooth.png");   // shared noise: never re-import it

            // import every texture first: Finish() validates all materials under Root
            foreach (var e in Elements)
            {
                ImportTexture(Root + "/Textures/T_Slash360_Crescent_" + e.name + ".png", 512);
                ImportTexture(Root + "/Textures/T_Slash360_EdgeCrescent_" + e.name + ".png", 512);
                Detail(Root + "/Textures/T_Slash360_Detail_" + e.name + ".png");
                ImportTexture(Root + "/Textures/T_Slash360_Ramp_" + e.name + ".png", 256);
            }
            Detail(Root + "/Textures/T_VFX_Gradient_01.png");
            Detail(Root + "/Textures/T_Slash360_Detail_Trail.png");

            foreach (var e in Elements) BuildElement(e, mesh, glow, white, dissolve);
        }

        public static void BuildBatch() => RunBatch(Build);

        // detail masks tile, so they repeat and are linear data
        static Texture2D Detail(string path)
        {
            ImportTexture(path, 256, false, false);
            var imp = (TextureImporter)AssetImporter.GetAtPath(path);
            if (imp.sRGBTexture) { imp.sRGBTexture = false; imp.SaveAndReimport(); }
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        static void BuildElement(Element e, Mesh mesh, Texture2D glow, Texture2D white, Texture2D dissolve)
        {
            string effect = "Slash360_" + e.name;
            string M(string part) => Root + "/Materials/M_" + effect + "_" + part + ".mat";
            string T(string n) => Root + "/Textures/" + n + ".png";
            var crescent = AssetDatabase.LoadAssetAtPath<Texture2D>(T("T_Slash360_Crescent_" + e.name));
            var edgeCrescent = AssetDatabase.LoadAssetAtPath<Texture2D>(T("T_Slash360_EdgeCrescent_" + e.name));
            var detail = AssetDatabase.LoadAssetAtPath<Texture2D>(T("T_Slash360_Detail_" + e.name));
            var trailDetail = AssetDatabase.LoadAssetAtPath<Texture2D>(T("T_Slash360_Detail_Trail"));
            var ramp = AssetDatabase.LoadAssetAtPath<Texture2D>(T("T_Slash360_Ramp_" + e.name));
            var gradient = AssetDatabase.LoadAssetAtPath<Texture2D>(T("T_VFX_Gradient_01"));

            bool additive = e.kind == "Additive";
            string bodyShader = additive ? ShAdd : e.kind == "Cutout" ? ShCut : ShAlpha;
            var blend = additive ? VfxBlend.Additive : VfxBlend.Alpha;

            // ---- materials (Coloso shaders)
            // Body: MaskTex = gradient (fades the mesh ends); dissolve = scrolling streak noise, so the end of the slash erodes in streaks.
            var mBody = Coloso(M("Body"), bodyShader, blend, crescent, gradient, Vector2.one, Vector2.zero, additive ? ramp : null,
                detail, e.tile, e.flow, false, 7f, e.window, e.opacity, Color.white, e.cutoff);
            // Edge: short hot leading edge, tail-first dissolve (the thin tail goes first)
            var mEdge = Coloso(M("Edge"), ShAdd, VfxBlend.Additive, edgeCrescent, gradient, Vector2.one, Vector2.zero, null,
                detail, e.tile, Vector2.zero, true, 1f, e.window * 0.55f, 0.75f, Color.Lerp(Color.white, e.mid, 0.45f), 0f);
            // Trail: long soft veil behind the crescent; MaskTex carries streaks scrolled along the swing for motion blur
            string trailShader = additive ? ShAdd : ShAlpha;
            var mTrail = Coloso(M("Trail"), trailShader, blend, crescent, trailDetail, new Vector2(9f, 2.2f), new Vector2(-5f, 0f), additive ? ramp : null,
                detail, e.tile, Vector2.zero, true, 1f, 0.95f, 0.35f, Color.white, 0f);

            var mFlash = Material(M("Flash"), VfxBlend.Additive, glow);
            var mDebris = e.debris == "spark"
                ? Spark(M("Debris"), e)
                : Material(M("Debris"), VfxBlend.Alpha, e.debris == "bubble" ? (Texture)glow : white);

            // ---- hierarchy: anchor -> tilted swing group
            var root = new GameObject("VFX_" + effect);
            var swing = Group(root.transform, "Swing");
            swing.localPosition = new Vector3(0f, HipHeight, 0f);
            swing.localRotation = Quaternion.Euler(Tilt, 0f, 0f);

            float scale = Radius / MeshOuter;
            RingLayer(swing, "L0_Trail", mTrail, mesh, scale * 0.985f, -1, 0.95f, additive ? null : new[] { e.mid, e.outer });   // slightly inside the body so its streaks never fringe the outer rim
            RingLayer(swing, "L1_Body", mBody, mesh, scale, 0, e.window, additive ? null : new[] { e.core, e.mid, e.outer });
            RingLayer(swing, "L2_Edge", mEdge, mesh, scale * 1.01f, 1, e.window * 0.55f, null);

            Debris(swing, e, mDebris, Swing * Life / (1f + e.window));

            var flash = Particle(swing, "L4_StartFlash", mFlash, lifetime: 0.1f, size: 0.9f, color: e.core);
            flash.transform.localPosition = new Vector3(0f, 0f, Radius * 0.97f);
            SizeOverLifetime(flash, 0f, 0.4f, 1f, 1.3f);
            AlphaOverLifetime(flash, 0f, 1f, 0.5f, 0.8f, 1f, 0f);
            flash.GetComponent<ParticleSystemRenderer>().sortingOrder = 3;

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + effect + ".prefab");
            var cam = new Vector3(0f, 1f + 5.5f * Mathf.Sin(60f * Mathf.Deg2Rad), -5.5f * Mathf.Cos(60f * Mathf.Deg2Rad));
            Finish(prefab, Root, effect, new[] { 0.04f, 0.09f, 0.14f, 0.2f, 0.28f, 0.34f }, cam, new Vector3(0f, 1f, 0f));
        }

        // One Coloso material. MainTex = baked grey crescent (x = l: 0 head .. 1 tail tip, y = v across the band),
        // tiling.x = -1/window so that the head position added from Custom1.z slides it round the ring.
        static Material Coloso(string path, string shader, VfxBlend blend, Texture2D main, Texture2D mask, Vector2 maskTile, Vector2 maskFlow, Texture2D ramp,
            Texture2D dissolve, Vector2 dissolveTile, Vector2 dissolveFlow, bool dissolveFromMain, float smoothDissolve,
            float window, float opacity, Color tint, float cutoff)
        {
            var m = Material(path, blend, main, shader);
            m.SetTextureScale("_MainTex", new Vector2(-1f / window, 1f));
            m.SetTextureOffset("_MainTex", Vector2.zero);
            m.SetColor("_MainColor", new Color(tint.r, tint.g, tint.b, 0f));
            m.SetFloat("_OpacityStrength", opacity);
            m.SetFloat("_TextureIntensity", 1f);
            m.SetFloat("_OpacityPower", 1f);
            m.SetFloat("_FD", 0f); m.SetFloat("_CDF", 0f); m.SetFloat("_CDFOffset", 0f); m.SetFloat("_CameraOffset", 0f);
            m.SetFloat("_CullMode", 2f);                         // top face only (the ring cross-section is a double-sided blade)
            m.SetFloat("_ZwriteMode", 0f);

            // main UV: head position comes from the particle (Custom1.zw -> uv2), clamped so the crescent is a single copy
            m.SetFloat("_MainUVSwitch", 0f);
            m.SetFloat("_UseMainUVCustom1ZW", 1f);
            m.SetFloat("_MainClampX", 1f); m.SetFloat("_MainClampY", 1f);
            m.SetFloat("_MainRIsAlpha", 0f);                     // alpha channel carries the crescent
            if (m.HasProperty("_MainRBGOffset")) { m.SetFloat("_MainRBGOffset", 0f); m.DisableKeyword("_MAINRBGOFFSET_ON"); }

            // MaskTex multiplies alpha (gradient: fades the ends of the mesh; streaks: scrolled motion blur)
            if (mask != null) m.SetTexture("_MaskTex", mask);
            m.SetTextureScale("_MaskTex", maskTile);
            m.SetFloat("_MaskFlowX", maskFlow.x); m.SetFloat("_MaskFlowY", maskFlow.y);

            // dissolve: Custom1.x drives it (UseManual off); from the crescent itself (tail first) or from a scrolling noise
            m.SetTexture("_DissolveTex", dissolve);
            m.SetTextureScale("_DissolveTex", dissolveTile);
            m.SetFloat("_DissolveFlowX", dissolveFlow.x); m.SetFloat("_DissolveFlowY", dissolveFlow.y);
            m.SetFloat("_MainTexRDissolve", dissolveFromMain ? 1f : 0f);
            m.SetFloat("_UseManual_DebugDissolve", 0f);
            m.SetFloat("_ManualDissolve", 1f);
            m.SetFloat("_SmoothDissolve", smoothDissolve);

            if (m.HasProperty("_ColorTex"))                      // Additive only: colour ramp across the band (x = mesh v)
            {
                if (ramp != null) m.SetTexture("_ColorTex", ramp);
                m.SetFloat("_Color90degreeUVFlip", ramp != null ? 1f : 0f);
                m.SetFloat("_ColorClampX", 1f); m.SetFloat("_ColorClampY", 1f);
                m.SetFloat("_ColorPower", 1f); m.SetFloat("_ColorIntensity", ramp != null ? 0f : 1f); m.SetFloat("_Desaturate", 0f);
            }
            if (m.HasProperty("_NoiseTex"))                      // Alpha / Cutout only: wobble the crescent with noise (Custom1.y scales it)
            {
                m.SetTexture("_NoiseTex", AssetDatabase.LoadAssetAtPath<Texture2D>(Noise + "T_Noise_Smooth.png"));
                m.SetTextureScale("_NoiseTex", new Vector2(3f, 1.3f));
                m.SetFloat("_UseNoise", 1f); m.EnableKeyword("_USENOISE_ON");
                m.SetFloat("_UseCustom1YDistortion", 1f); m.EnableKeyword("_USECUSTOM1YDISTORTION_ON");
                m.SetFloat("_MainTexDistortion", 1f);
                m.SetFloat("_NoiseAffectsXAxis", 0.03f); m.SetFloat("_NoiseAffectsYAxis", 0.04f);
                m.SetFloat("_NoiseFlowX", 0.5f); m.SetFloat("_NoiseFlowY", 0f);
            }
            if (m.HasProperty("_AlphaCutOut")) m.SetFloat("_AlphaCutOut", Mathf.Clamp(cutoff, 0.01f, 0.99f));
            EditorUtility.SetDirty(m);
            return m;
        }

        static Material Spark(string path, Element e)
        {
            var m = Material(path, e.kind == "Additive" ? VfxBlend.Additive : VfxBlend.Alpha, null, "VFX/FX/Spark");
            m.DisableKeyword("_USE_PARTICLE_DATA");
            m.SetFloat("_UseParticle", 0f);
            m.SetFloat("_Shrink", 0f);
            m.SetColor("_ColorHead", e.core);
            m.SetColor("_ColorTail", e.mid);
            m.SetFloat("_Taper", 0.55f);       // capsule with a tail, not a cone
            m.SetFloat("_HeadSize", 0.4f);
            m.SetFloat("_Soft", 0.5f);
            EditorUtility.SetDirty(m);
            return m;
        }

        // One mesh particle; the Coloso shader reads dissolve / distortion / UV offset from Custom1 (XYZW).
        // lifeColors: colour over lifetime (Alpha / Cutout shaders have no colour ramp); null = white, alpha fade only.
        static void RingLayer(Transform parent, string name, Material mat, Mesh mesh, float scale, int order, float window, Color[] lifeColors)
        {
            var ps = Particle(parent, name, mat, lifetime: Life, size: scale);
            var cd = ps.customData;
            cd.enabled = true;

            // Custom1: x dissolve (1 visible; erosion runs below ~0.5), y distortion multiplier, z head position / window, w unused
            float last = (1f + window) / window;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 4);
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, new ParticleSystem.MinMaxCurve(1f, Lin(0f, 1f, 0.55f, 0.65f, 1f, 0f)));
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, new ParticleSystem.MinMaxCurve(1f));
            cd.SetVector(ParticleSystemCustomData.Custom1, 2, new ParticleSystem.MinMaxCurve(1f, Lin(0f, 0f, Swing, last, 1f, last)));
            cd.SetVector(ParticleSystemCustomData.Custom1, 3, new ParticleSystem.MinMaxCurve(0f));

            if (lifeColors != null) ColorOverLifetime(ps, lifeColors, 0f, 1f, 0.85f, 1f, 1f, 0f);
            else AlphaOverLifetime(ps, 0f, 1f, 0.85f, 1f, 1f, 0f);

            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Mesh;
            r.alignment = ParticleSystemRenderSpace.Local;
            r.mesh = mesh;
            r.sortingOrder = order;
            r.enableGPUInstancing = false;
            r.SetActiveVertexStreams(new List<ParticleSystemVertexStream>
            {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Color, ParticleSystemVertexStream.UV,
                ParticleSystemVertexStream.Custom1XYZW
            });
        }

        // piecewise linear curve through (t, value) pairs
        static AnimationCurve Lin(params float[] tv)
        {
            var c = new AnimationCurve();
            for (int i = 0; i < tv.Length; i += 2) c.AddKey(tv[i], tv[i + 1]);
            for (int i = 0; i < c.length; i++)
            {
                AnimationUtility.SetKeyLeftTangentMode(c, i, AnimationUtility.TangentMode.Linear);
                AnimationUtility.SetKeyRightTangentMode(c, i, AnimationUtility.TangentMode.Linear);
            }
            return c;
        }

        // Element debris leaves the ring where the head is: circle shape in Loop arc mode, one lap in sweepEnd seconds.
        static void Debris(Transform parent, Element e, Material mat, float sweepEnd)
        {
            bool mesh = e.debris == "crystal" || e.debris == "rock";
            int count = e.debris == "bubble" ? 12 : mesh ? 10 : 16;
            var ps = Particle(parent, "L3_Debris", mat, lifetime: 0.3f, size: 0.12f, color: Color.white);
            // shape circle: starts at +z (the mesh seam) and runs clockwise seen from above, like u on the mesh
            ps.transform.localRotation = Quaternion.AngleAxis(-120f, new Vector3(1f, 1f, 1f));
            var main = ps.main;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.18f, 0.32f);
            main.maxParticles = 60;

            var em = ps.emission;
            em.SetBursts(new[] { new ParticleSystem.Burst(0.01f, (short)1, (short)1, count, sweepEnd / count) });

            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Circle;
            shape.radius = Radius * 0.97f;
            shape.radiusThickness = 0f;
            shape.arc = 360f;
            shape.arcMode = ParticleSystemShapeMultiModeValue.Loop;
            shape.arcSpread = 0f;
            shape.arcSpeed = new ParticleSystem.MinMaxCurve(1f / sweepEnd);

            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.sortingOrder = 2;
            switch (e.debris)
            {
                case "spark":
                    main.startSpeed = e.name == "Lightning" ? new ParticleSystem.MinMaxCurve(1.2f, 2.8f) : new ParticleSystem.MinMaxCurve(0.8f, 2.2f);
                    main.startSize = e.name == "Lightning" ? new ParticleSystem.MinMaxCurve(0.07f, 0.14f) : new ParticleSystem.MinMaxCurve(0.08f, 0.17f);
                    main.gravityModifier = e.name == "Fire" ? -0.25f : 0f;
                    r.renderMode = ParticleSystemRenderMode.Stretch;
                    r.lengthScale = e.name == "Lightning" ? 3.5f : 2.2f;
                    r.velocityScale = 0.05f;
                    AlphaOverLifetime(ps, 0f, 1f, 0.7f, 1f, 1f, 0f);
                    break;
                case "bubble":
                    main.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 0.9f);
                    main.startSize = new ParticleSystem.MinMaxCurve(0.1f, 0.24f);
                    main.startColor = new ParticleSystem.MinMaxGradient(e.mid, e.core);
                    main.gravityModifier = -0.2f;
                    SizeOverLifetime(ps, 0f, 0.3f, 0.4f, 1f, 1f, 0.8f);
                    AlphaOverLifetime(ps, 0f, 0.9f, 0.6f, 0.8f, 1f, 0f);
                    break;
                default: // crystal / rock: small solid chunks flung off the ring
                    main.startSpeed = new ParticleSystem.MinMaxCurve(1.0f, 2.4f);
                    main.startSize = e.debris == "crystal" ? new ParticleSystem.MinMaxCurve(0.2f, 0.38f) : new ParticleSystem.MinMaxCurve(0.18f, 0.34f);
                    main.startRotation3D = true;
                    main.startRotationX = new ParticleSystem.MinMaxCurve(0f, 6.28f);
                    main.startRotationY = new ParticleSystem.MinMaxCurve(0f, 6.28f);
                    main.startRotationZ = new ParticleSystem.MinMaxCurve(0f, 6.28f);
                    main.startColor = new ParticleSystem.MinMaxGradient(e.mid, e.core);
                    main.gravityModifier = e.debris == "rock" ? 1.8f : 0.4f;
                    SizeOverLifetime(ps, 0f, 0.6f, 0.7f, 1f, 1f, 0f);
                    r.renderMode = ParticleSystemRenderMode.Mesh;
                    string a = e.debris == "crystal" ? "SM_VFX_Debris_Crystal_01" : "SM_VFX_Spike";
                    string b = e.debris == "crystal" ? "SM_VFX_Debris_Crystal_02" : "SM_VFX_Debris_Crystal_01";
                    r.SetMeshes(new[] { Load(a), Load(b) });
                    r.alignment = ParticleSystemRenderSpace.Local;
                    break;
            }
        }

        static Mesh Load(string n)
        {
            var m = AssetDatabase.LoadAssetAtPath<Mesh>("Assets/VFX/_Imported/Mesh/" + n + ".fbx");
            if (m == null) throw new System.InvalidOperationException("Mesh missing: " + n);
            return m;
        }
    }
}
#endif
